import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"联盟","description":"","frontmatter":{},"headers":[],"relativePath":"towns/index.md","filePath":"towns/index.md"}'),n={name:"towns/index.md"};function r(c,t,i,l,h,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="联盟" tabindex="-1">联盟 <a class="header-anchor" href="#联盟" aria-label="Permalink to &quot;联盟&quot;">​</a></h1><p>联盟是服务器团队玩法的核心，允许玩家建立自治团体，共同<a href="./Claims.html">圈占领地</a>、共享资源。每位玩家只能加入一个联盟，每个联盟有一位盟主。</p><blockquote><p>联盟系统由服务器自研插件 <strong>PepperUnion</strong> 提供，所有指令以 <code>/union</code> 开头。</p></blockquote><h2 id="创建联盟" tabindex="-1">创建联盟 <a class="header-anchor" href="#创建联盟" aria-label="Permalink to &quot;创建联盟&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/union create &lt;名字&gt;</span></span></code></pre></div><p>输入命令后<strong>再次输入 <code>/union confirm</code></strong> 确认（5 秒内有效），即可创建联盟：</p><ul><li>创建消耗 <strong>64 钻石</strong>（从你的余额扣除）。</li><li>名字支持中文，最长 24 个字符，不能包含空格。</li><li>创建后你自动成为<strong>盟主</strong>，联盟为 1 级。</li></ul><h2 id="加入联盟" tabindex="-1">加入联盟 <a class="header-anchor" href="#加入联盟" aria-label="Permalink to &quot;加入联盟&quot;">​</a></h2><p>联盟有三种加入策略（由盟主通过 <code>/union config</code> 设置）：</p><table tabindex="0"><thead><tr><th>策略</th><th>说明</th><th>加入方式</th></tr></thead><tbody><tr><td><strong>OPEN（开放）</strong></td><td>任何玩家可直接加入</td><td><code>/union join &lt;联盟编号&gt;</code></td></tr><tr><td><strong>APPLY（申请）</strong></td><td>需要提交申请，由管理成员审核</td><td><code>/union apply &lt;联盟编号&gt; &lt;留言&gt;</code>，管理成员用 <code>/union audit</code> 审核</td></tr><tr><td><strong>CLOSED（关闭）</strong></td><td>只能通过邀请加入</td><td>等待邀请后 <code>/union accept &lt;联盟编号&gt;</code></td></tr></tbody></table><p><strong>邀请成员</strong>（需邀请权限）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/union invite &lt;玩家&gt;</span></span></code></pre></div><p>被邀请的玩家输入 <code>/union accept &lt;联盟编号&gt;</code> 即可入盟。邀请有效期为 <strong>10 分钟</strong>。</p><p><strong>查看联盟：</strong></p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/union list</code></td><td>查看全部联盟列表</td></tr><tr><td><code>/union info [联盟编号]</code></td><td>查看联盟详情（等级、经验、盟主、成员数等；不填编号查看自己的联盟）</td></tr><tr><td><code>/union gui</code></td><td>打开联盟图形界面</td></tr></tbody></table><h2 id="成员管理" tabindex="-1">成员管理 <a class="header-anchor" href="#成员管理" aria-label="Permalink to &quot;成员管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th><th>权限</th></tr></thead><tbody><tr><td><code>/union kick &lt;玩家&gt;</code></td><td>踢出成员</td><td>踢人权限</td></tr><tr><td><code>/union ban &lt;玩家&gt; [原因]</code></td><td>拉黑玩家（禁止其再加入）</td><td>踢人权限</td></tr><tr><td><code>/union unban &lt;玩家&gt;</code></td><td>解除拉黑</td><td>踢人权限</td></tr><tr><td><code>/union leave</code></td><td>退出当前联盟（盟主需先转让或解散）</td><td>本人</td></tr><tr><td><code>/union rank set &lt;玩家&gt; &lt;职位&gt;</code></td><td>调整成员职位</td><td>分配权限</td></tr></tbody></table><h2 id="盟主专属" tabindex="-1">盟主专属 <a class="header-anchor" href="#盟主专属" aria-label="Permalink to &quot;盟主专属&quot;">​</a></h2><p>以下操作<strong>仅盟主</strong>可以执行：</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/union transfer &lt;玩家&gt;</code></td><td>转让盟主</td></tr><tr><td><code>/union disband</code></td><td>解散联盟（需 <code>/union confirm</code> 二次确认）</td></tr><tr><td><code>/union rename &lt;新名字&gt;</code></td><td>联盟改名</td></tr><tr><td><code>/union rank create/delete/setperm</code></td><td>管理职位定义</td></tr><tr><td><code>/union setitem</code></td><td>把手中物品设为联盟头像</td></tr><tr><td><code>/union config set &lt;键&gt; &lt;值&gt;</code></td><td>修改联盟配置</td></tr></tbody></table><h2 id="联盟配置" tabindex="-1">联盟配置 <a class="header-anchor" href="#联盟配置" aria-label="Permalink to &quot;联盟配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/union config list</code></td><td>查看当前配置</td></tr><tr><td><code>/union config get &lt;键&gt;</code></td><td>查看某项配置</td></tr><tr><td><code>/union config set &lt;键&gt; &lt;值&gt;</code></td><td>修改配置</td></tr></tbody></table><p>常用配置项：</p><table tabindex="0"><thead><tr><th>配置键</th><th>说明</th><th>可选值</th></tr></thead><tbody><tr><td><code>joinPolicy</code></td><td>加入策略</td><td><code>OPEN</code> / <code>APPLY</code> / <code>CLOSED</code></td></tr><tr><td><code>announcement</code></td><td>联盟公告</td><td>任意文本</td></tr><tr><td><code>defaultRank</code></td><td>新成员默认职位</td><td>职位 ID</td></tr><tr><td><code>avatar</code></td><td>联盟头像物品</td><td>用 <code>/union setitem</code> 设置</td></tr></tbody></table><h2 id="联盟账户" tabindex="-1">联盟账户 <a class="header-anchor" href="#联盟账户" aria-label="Permalink to &quot;联盟账户&quot;">​</a></h2><p>联盟拥有独立的金库账户，用于存钱、拨款与<a href="./Claims.html#额度与经济">领地额度购买</a>。</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th><th>权限</th></tr></thead><tbody><tr><td><code>/union account balance</code></td><td>查看账户余额</td><td>所有人</td></tr><tr><td><code>/union account deposit &lt;金额&gt;</code></td><td>存入钻石</td><td>存款权限</td></tr><tr><td><code>/union account withdraw &lt;金额&gt;</code></td><td>取出钻石</td><td>取款权限</td></tr><tr><td><code>/union account give &lt;玩家&gt; &lt;金额&gt;</code></td><td>拨款给成员</td><td>拨款权限</td></tr><tr><td><code>/union account log [条数]</code></td><td>查看账户流水</td><td>流水权限</td></tr><tr><td><code>/union logs [条数]</code></td><td>查看联盟操作日志</td><td>视权限</td></tr></tbody></table><h2 id="联盟聊天" tabindex="-1">联盟聊天 <a class="header-anchor" href="#联盟聊天" aria-label="Permalink to &quot;联盟聊天&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/union chat &lt;消息&gt;</code></td><td>向联盟成员发送内部消息</td></tr></tbody></table><h2 id="等级与经验" tabindex="-1">等级与经验 <a class="header-anchor" href="#等级与经验" aria-label="Permalink to &quot;等级与经验&quot;">​</a></h2><p>联盟通过积累<strong>经验</strong>升级，等级越高成员上限越多：</p><table tabindex="0"><thead><tr><th>等级</th><th>升级所需累计经验</th><th>成员上限</th></tr></thead><tbody><tr><td>1</td><td>-</td><td>10</td></tr><tr><td>2</td><td>100</td><td>20</td></tr><tr><td>3</td><td>300</td><td>35</td></tr><tr><td>4</td><td>600</td><td>50</td></tr><tr><td>5</td><td>1000</td><td>70</td></tr><tr><td>6</td><td>1500</td><td>100</td></tr></tbody></table><blockquote><p>经验为累计值，升级不清空。等级最高 10 级（7 级起的累计经验要求为 2100 / 2800 / 3600 / 4500）。</p></blockquote><p>联盟经验通过成员活跃度获得（如<a href="./Advancements.html">领地繁荣度</a>联动上报）。</p><h2 id="pvp-保护" tabindex="-1">PvP 保护 <a class="header-anchor" href="#pvp-保护" aria-label="Permalink to &quot;PvP 保护&quot;">​</a></h2><ul><li>默认情况下，<strong>同联盟成员之间无法互相攻击</strong>（包括弓箭等远程伤害）。</li><li>盟主不受此限制（可通过职位权限 <code>union.pvp.attackAlly</code> / <code>union.pvp.attackedByAlly</code> 为指定职位开放）。</li></ul><h2 id="小提示" tabindex="-1">小提示 <a class="header-anchor" href="#小提示" aria-label="Permalink to &quot;小提示&quot;">​</a></h2><ul><li>忘记命令？随时输入 <code>/union help</code> 查看帮助。</li><li>联盟需要成员活跃维护，长时间无人管理的联盟可能被清理。</li><li>联盟相关权限体系详见 <a href="./Roles.html">职位与权限</a>。</li></ul>',38)])])}const p=d(n,[["render",r]]);export{b as __pageData,p as default};
